 public static final BlockPos M=new BlockPos(24008,180,8),F=M.east(40);
 static int stage,ticks;static ServerPlayer actor;static InfusionMatrix matrix;static int expected,initial;public static volatile boolean scene,started,finished;static final List<ItemEntity> drops=new ArrayList<>();
 static String mode(){return System.getProperty("thaumcraft.infusionProbe","");}
 static void force(ServerLevel l,BlockPos p){for(int x=-1;x<=1;x++)for(int z=-1;z<=1;z++)l.setChunkForced((p.getX()>>4)+x,(p.getZ()>>4)+z,true);l.getChunkAt(p);}
 static ServerPlayer fake(ServerLevel l){var p=new ServerPlayer(l.getServer(),l,new GameProfile(UUID.fromString("3d875451-59b7-4ffc-aa47-b46ce806d2b2"),"InfusionFinish"),ClientInformation.createDefault());new net.minecraft.server.network.ServerGamePacketListenerImpl(l.getServer(),new net.minecraft.network.Connection(net.minecraft.network.protocol.PacketFlow.SERVERBOUND),p,net.minecraft.server.network.CommonListenerCookie.createInitial(p.getGameProfile(),false));l.addNewPlayer(p);for(int n=0;n<60;n++)p.connection.tickClientLoadTimeout();check(p.connection.hasClientLoaded(),"Native fixture player is still loading");p.setNoGravity(true);return p;}
 static void grant(ServerPlayer p){for(var k:List.of("INFUSION","INFUSIONANCIENT","INFUSIONELDRITCH","INFUSIONENCHANTMENT","CRYSTALFARMER","UNLOCKINFUSION","THEORYRESEARCH","UNLOCKGOLEMANCY"))ResearchService.grant(p,k);}
 @SubscribeEvent public static void login(net.minecraftforge.event.entity.player.PlayerEvent.PlayerLoggedInEvent e){if(mode().equals("finish-client")&&e.getEntity() instanceof ServerPlayer p){actor=p;p.setGameMode(net.minecraft.world.level.GameType.CREATIVE);}}
 @SubscribeEvent public static void drop(net.minecraftforge.event.entity.EntityJoinLevelEvent e){if(mode().startsWith("finish")){if(e.getEntity() instanceof ItemEntity i)drops.add(i);M16FinishChecks.join(e.getEntity());}}
 @SubscribeEvent public static void read(net.minecraftforge.event.server.ServerStartedEvent e){if(!mode().equals("finish-read"))return;var l=e.getServer().overworld();force(l,M);matrix=(InfusionMatrix)l.getBlockEntity(M);check(matrix!=null&&matrix.supported()&&matrix.job()!=null&&matrix.snapshot().offeringTicks()>0&&matrix.job().remaining().isEmpty()&&matrix.job().consumed()==0,"Saved ingredient animation not recovered");check(InfusionEnchantments.warp(((InfusionPedestal)l.getBlockEntity(M.offset(4,-2,4))).item())==1,"Item warping lost on restart");M16FinishChecks.read(l);stage=10;Thaumcraft.LOGGER.info("INFUSION55_RESTART_LOADED: version-one data, paid essence and partial ingredient animation, warped tool preserved");}
 static void styles(ServerLevel l){for(var style:List.of("arcane","ancient","eldritch")){var m=altar(l,M,actor);if(!style.equals("arcane")){l.setBlockAndUpdate(M.below(2),(style.equals("ancient")?InfusionContent.ANCIENT:InfusionContent.ELDRITCH).get().defaultBlockState());((InfusionPedestal)l.getBlockEntity(M.below(2))).setItem(thaumcraft.crystals.CrystalContent.essence("aer",1));for(int x:new int[]{-1,1})for(int z:new int[]{-1,1})l.setBlockAndUpdate(M.offset(x,-2,z),SimpleContent.BLOCKS.get("pillar_"+style).get().defaultBlockState());}m.surroundings();check(m.cycleDelay()==(style.equals("arcane")?5:style.equals("ancient")?4:3),"Wrong altar speed "+style);check(m.start(actor),"Cannot start altar "+style);load(m,new InfusionState(1,25,0,Optional.of(m.job())));int paid=thaumcraft.alchemy.AspectAmounts.total(m.job().remaining());for(int n=0;n<400;n++)m.serverTick();check(m.job()==null&&((InfusionPedestal)l.getBlockEntity(M.below(2))).item().is(thaumcraft.crystals.CrystalContent.BLOCKS.get("aer").get().asItem())&&essence(l,M)==25-paid,"Wrong altar conservation "+style);}
  Thaumcraft.LOGGER.info("INFUSION55_STYLES_OK: arcane/ancient/eldritch native cycles, exact costs and single output");
 }
 static void symmetry(ServerLevel l){var m=altar(l,M,actor);var a=M.offset(-4,-2,2);var b=M.offset(4,-2,-2);m.surroundings();float base=m.replenish();l.setBlockAndUpdate(a,InfusionContent.INLAY.get().defaultBlockState());m.surroundings();check(Math.abs(m.replenish()-base+.1F)<.0001,"Asymmetric inlay did not use original minimum penalty");l.setBlockAndUpdate(b,InfusionContent.INLAY.get().defaultBlockState());m.surroundings();check(Math.abs(m.replenish()-base-.025F)<.0001,"Inlay pair changed value");l.setBlockAndUpdate(a,Blocks.SKELETON_SKULL.defaultBlockState());l.setBlockAndUpdate(b,Blocks.WITHER_SKELETON_SKULL.defaultBlockState());m.surroundings();check(Math.abs(m.replenish()-base-.1F)<.0001,"Modern skull variants did not share original family");Thaumcraft.LOGGER.info("INFUSION55_SYMMETRY_OK: minimum asymmetric penalty, exact inlay pair and shared skull family");}
 static ItemStack warped(){var tool=new ItemStack(Items.DIAMOND_PICKAXE);tool.setDamageValue(37);tool.set(DataComponents.CUSTOM_NAME,Component.literal("Stable infused tool"));tool.enchant(actor.registryAccess().lookupOrThrow(Registries.ENCHANTMENT).getOrThrow(net.minecraft.world.item.enchantment.Enchantments.UNBREAKING),2);var before=InfusionEnchantments.apply(tool,InfusionEnchantments.Kind.COLLECTOR);var result=InfusionEnchantments.commitWarp(before,InfusionEnchantments.apply(before,InfusionEnchantments.Kind.SOUNDING),0);check(InfusionEnchantments.warp(result)==1&&InfusionEnchantments.warp(before)==0&&result.getDamageValue()==37&&result.getHoverName().getString().equals("Stable infused tool")&&result.getEnchantments().equals(tool.getEnchantments()),"Item warp lost components or mutated input");actor.setItemInHand(InteractionHand.MAIN_HAND,result);check(thaumcraft.warp.WarpEngine.gear(actor)>=1,"Infusion warp not connected to equipped warp");check(InfusionEnchantments.warp(InfusionEnchantments.commitWarp(before,result,9))==1,"Non-increasing draw lost existing warp");return result;}
 static void recovery(ServerLevel l){var m=altar(l,M,actor);check(m.start(actor),"Cannot start relocation test");load(m,new InfusionState(1,25,0,Optional.of(m.job())));for(int n=0;n<125;n++)m.serverTick();check(m.job().remaining().isEmpty(),"Test failed exact essence payment");var offer=m.job().offerings().getFirst();var from=(InfusionPedestal)l.getBlockEntity(offer.position(M));var moved=from.item();from.setItem(ItemStack.EMPTY);pedestal(l,M.south(3).below(2),moved);for(int n=0;n<200;n++)m.serverTick();check(m.job()==null&&essence(l,M)==0,"Moved offering did not recover");
  m=altar(l,M,actor);check(m.start(actor),"Cannot start missing ingredient test");load(m,new InfusionState(1,25,0,Optional.of(m.job())));for(int n=0;n<125;n++)m.serverTick();offer=m.job().offerings().getFirst();from=(InfusionPedestal)l.getBlockEntity(offer.position(M));moved=from.item();from.setItem(ItemStack.EMPTY);for(int n=0;n<20;n++)m.serverTick();check(m.job()!=null&&m.status().equals("missing_item"),"Missing ingredient did not pause");from.setItem(moved);for(int n=0;n<200;n++)m.serverTick();check(m.job()==null&&essence(l,M)==0,"Replaced offering did not resume");
  m=altar(l,M,actor);check(m.start(actor),"Cannot start tamper test");((InfusionPedestal)l.getBlockEntity(M.below(2))).setItem(new ItemStack(Items.DIRT));for(int n=0;n<10;n++)m.serverTick();check(m.job()==null&&((InfusionPedestal)l.getBlockEntity(M.below(2))).item().is(Items.DIRT)&&essence(l,M)==25,"Central tampering produced free output");Thaumcraft.LOGGER.info("INFUSION55_RECOVERY_OK: relocation, missing offering pause/return, exact payment, central tamper rejection");
 }
 static List<Zombie> targets(ServerLevel l){var out=new ArrayList<Zombie>();for(int n=0;n<2;n++){var z=new Zombie(EntityTypes.ZOMBIE,l);z.setNoAi(true);z.setNoGravity(true);z.getAttribute(net.minecraft.world.entity.ai.attributes.Attributes.MAX_HEALTH).setBaseValue(100);z.setHealth(100);z.setPos(Vec3.atCenterOf(F.offset(n*2-1,0,3)));check(l.addFreshEntity(z),"Cannot add fault target");out.add(z);}return out;}
 static void accidents(ServerLevel l){force(l,F);for(var p:BlockPos.betweenClosed(F.offset(-5,-3,-5),F.offset(5,2,5)))l.setBlockAndUpdate(p,p.getY()==F.getY()-3?Blocks.STONE.defaultBlockState():Blocks.AIR.defaultBlockState());var pos=F.west(3).below(2);actor.setPos(Vec3.atCenterOf(M));
  for(int draw=0;draw<24;draw++){l.setBlockAndUpdate(pos.above(),Blocks.AIR.defaultBlockState());var ped=pedestal(l,pos,new ItemStack(Items.DIAMOND));var targets=targets(l);int old=drops.size();float flux=thaumcraft.aura.AuraManager.get(l,pos).flux();var kind=InfusionMishaps.kind(draw);InfusionMishaps.apply(l,F,List.of(pos),draw);boolean item=Set.of(InfusionMishaps.Kind.EJECT,InfusionMishaps.Kind.EJECT_GOO,InfusionMishaps.Kind.EJECT_GOO_ALT,InfusionMishaps.Kind.EJECT_FLUX,InfusionMishaps.Kind.DESTROY_FLUX,InfusionMishaps.Kind.EJECT_EXPLOSION).contains(kind);if(item){check(ped.item().isEmpty(),"Ingredient accident did not remove input "+draw);check(drops.subList(old,drops.size()).stream().filter(e->e.getItem().is(Items.DIAMOND)).mapToInt(e->e.getItem().getCount()).sum()==(draw==17?0:1),"Ingredient accident duplicated/lost drop "+draw);}else check(ped.item().is(Items.DIAMOND),"Non-item accident consumed offering "+draw);
   if(draw==12||draw==13||draw==16)check(l.getBlockState(pos.above()).is(TaintContent.GOO.get()),"No flux goo "+draw);if(draw==14||draw==15||draw==17)check(thaumcraft.aura.AuraManager.get(l,pos).flux()-flux>=5,"No accident flux "+draw);
   if(draw>=7&&draw<=11)check(targets.stream().filter(z->z.getHealth()<100).count()==(draw<10?1:2),"Wrong zap targets "+draw);if(draw==18||draw==19||draw==22)check(targets.stream().filter(z->z.hasEffect(TaintContent.DISEASE.getHolder().orElseThrow())||z.hasEffect(TaintContent.EXHAUST.getHolder().orElseThrow())).count()==(draw==22?2:1),"Wrong disease targets "+draw);check(l.getBlockState(F.below(3)).is(Blocks.STONE)&&l.getBlockEntity(pos)==ped,"Accident explosion destroyed terrain");targets.forEach(Entity::discard);drops.subList(old,drops.size()).forEach(Entity::discard);
  }
  actor.setPos(Vec3.atCenterOf(F));for(int n=0;n<32;n++){l.getRandom().setSeed(1000+n);InfusionMishaps.apply(l,F,List.of(pos),4);}var warp=PlayerWarpStore.read(actor).getOrThrow();check(warp.normal()>0&&warp.temporary()>0&&ResearchService.state(actor).flags().contains("!INSTABILITY"),"Warp variants or discovery missing");actor.setPos(Vec3.atCenterOf(M));
  for(int draw:new int[]{0,12,14,16,17,20}){l.setBlockAndUpdate(pos.above(),Blocks.AIR.defaultBlockState());var ped=pedestal(l,pos,new ItemStack(Items.DIAMOND));var sourcePos=pos.east();l.setBlockAndUpdate(sourcePos,InfusionContent.STABILIZER.get().defaultBlockState());var source=(StabilizationEntity)l.getBlockEntity(sourcePos);for(int n=0;n<300;n++)source.serverTick();int old=drops.size();check(InfusionMishaps.apply(l,F,List.of(pos),draw)&&source.energy()>=5&&source.energy()<=10&&ped.item().is(Items.DIAMOND)&&drops.size()==old&&l.getBlockState(pos.above()).isAir(),"Mitigation did not prevent paid ingredient accident "+draw);l.setBlockAndUpdate(sourcePos,Blocks.AIR.defaultBlockState());}
  thaumcraft.config.ThaumcraftConfig.wussMode.set(true);var targets=targets(l);InfusionMishaps.apply(l,F,List.of(pos),11);InfusionMishaps.apply(l,F,List.of(pos),22);check(targets.stream().allMatch(z->z.getHealth()==100&&z.getActiveEffects().isEmpty()),"Wuss mode ignored");targets.forEach(Entity::discard);thaumcraft.config.ThaumcraftConfig.wussMode.set(false);Thaumcraft.LOGGER.info("INFUSION55_ACCIDENTS_OK: all 24 draws, six exact item outcomes, goo/flux, one/all damage and disease, both warp variants, discovery, six paid mitigations, nondestructive explosions and wuss mode");
 }
 static void dynamic(ServerLevel l){var recipe=(InfusionRecipe)l.recipeAccess().getRecipes().stream().filter(h->h.value() instanceof InfusionRecipe r&&r.enchantment().equals("runic")).findFirst().orElseThrow().value();var armor=new ItemStack(Items.LEATHER_CHESTPLATE);armor.setDamageValue(12);armor.set(DataComponents.CUSTOM_NAME,Component.literal("Runic proof"));for(int rank=0;rank<9;rank++){var parts=new ArrayList<ItemStack>();parts.add(new ItemStack(thaumcraft.crafting.ArcaneContent.SALIS.get()));for(int n=0;n<=rank;n++)parts.add(new ItemStack(BasicContent.AMBER.get()));var input=new InfusionInput(armor,parts);check(recipe.matches(input,l)&&recipe.aspects(input).get("praemunio")==20+20*(1<<rank),"Runic recipe rank/cost mismatch");armor=recipe.assemble(input);check(thaumcraft.equipment.EquipmentContent.runic(armor)==rank+1&&armor.getDamageValue()==12&&armor.getHoverName().getString().equals("Runic proof"),"Runic augment lost components");}check(!thaumcraft.equipment.EquipmentContent.canAugment(armor),"Runic cap bypassed");var helm=new ItemStack(SimpleContent.ITEMS.get("fortress_helm").get());helm.setDamageValue(9);for(var key:List.of("fortress_goggles","mask_0","mask_1","mask_2")){helm=thaumcraft.equipment.FortressMasks.apply(helm,key);check(!helm.isEmpty()&&helm.getDamageValue()==9,"Fortress infusion lost components");}check(helm.get(thaumcraft.equipment.FortressMasks.GOGGLES.get())&&helm.get(thaumcraft.equipment.FortressMasks.MASK.get())==2,"Fortress upgrades do not coexist");Thaumcraft.LOGGER.info("INFUSION55_DYNAMIC_OK: nine runic ranks/costs/cap and four fortress upgrades preserve components");}
 static void prepareSave(ServerLevel l){matrix=altar(l,M,actor);check(matrix.start(actor),"Cannot start saved job");load(matrix,new InfusionState(1,25,0,Optional.of(matrix.job())));while(!matrix.job().remaining().isEmpty())matrix.serverTick();while(matrix.snapshot().offeringTicks()<3)matrix.serverTick();pedestal(l,M.offset(4,-2,4),warped());Thaumcraft.LOGGER.info("INFUSION55_SAVED: all essence paid, zero ingredients consumed, partial absorption animation and warped tool");}
 static void clientScene(ServerLevel l){l.getServer().clockManager().setTotalTicks(l.dimensionType().defaultClock().orElseThrow(),6000);actor.addEffect(new net.minecraft.world.effect.MobEffectInstance(net.minecraft.world.effect.MobEffects.NIGHT_VISION,12000,0,false,false));force(l,M);grant(actor);for(int dx:new int[]{-12,12}){var at=M.east(dx);var m=altar(l,at,actor);var style=dx<0?"ancient":"eldritch";l.setBlockAndUpdate(at.below(2),(dx<0?InfusionContent.ANCIENT:InfusionContent.ELDRITCH).get().defaultBlockState());for(int x:new int[]{-1,1})for(int z:new int[]{-1,1})l.setBlockAndUpdate(at.offset(x,-2,z),SimpleContent.BLOCKS.get("pillar_"+style).get().defaultBlockState());m.surroundings();}
  matrix=altar(l,M,actor);var tool=new ItemStack(Items.DIAMOND_PICKAXE);for(int n=0;n<3;n++)tool=InfusionEnchantments.apply(tool,InfusionEnchantments.Kind.SOUNDING);tool=InfusionEnchantments.apply(tool,InfusionEnchantments.Kind.COLLECTOR);tool.set(DataComponents.CUSTOM_NAME,Component.literal("Advanced infusion proof"));((InfusionPedestal)l.getBlockEntity(M.below(2))).setItem(tool);var book=new ItemStack(Items.ENCHANTED_BOOK);book.enchant(l.registryAccess().lookupOrThrow(Registries.ENCHANTMENT).getOrThrow(net.minecraft.world.item.enchantment.Enchantments.SHARPNESS),1);((InfusionPedestal)l.getBlockEntity(M.offset(-3,-2,0))).setItem(book);((InfusionPedestal)l.getBlockEntity(M.offset(3,-2,0))).setItem(new ItemStack(Items.MAP));jar(l,M.offset(-4,-2,0),"sensus",200);jar(l,M.offset(0,-2,4),"ignis",250);jar(l,M.offset(0,-2,-4),"ignis",50);for(int x:new int[]{-1,1})for(int z:new int[]{-1,1})l.setBlockAndUpdate(M.offset(x,-3,z),SimpleContent.BLOCKS.get("matrix_cost").get().defaultBlockState());
  var candles=LuminousContent.BLOCKS.entrySet().stream().filter(e->e.getKey().startsWith("candle_")).toList();for(int n=0;n<16;n++){int x=2+n/4,z=1+n%4;l.setBlockAndUpdate(M.offset(x,-2,z),candles.get(n).getValue().get().defaultBlockState());l.setBlockAndUpdate(M.offset(-x,-2,-z),candles.get(n).getValue().get().defaultBlockState());}for(var item:l.getEntitiesOfClass(ItemEntity.class,new AABB(M).inflate(24)))item.discard();matrix.surroundings();actor.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(SimpleContent.ITEMS.get("caster_basic").get()));var eye=Vec3.atCenterOf(M).add(0,.5,3.5);var d=Vec3.atCenterOf(M).subtract(eye.add(0,1.62,0));float pitch=(float)-Math.toDegrees(Math.atan2(d.y,Math.sqrt(d.x*d.x+d.z*d.z)));actor.teleportTo(l,eye.x,eye.y,eye.z,Set.of(),180,pitch,true);actor.getAbilities().flying=true;actor.onUpdateAbilities();actor.setNoGravity(true);scene=true;Thaumcraft.LOGGER.info("INFUSION55_CLIENT_READY: real gauntlet interaction can start rank-four tool infusion with four cost upgrades and 500 available essence");
 }
 @SubscribeEvent public static void tick(TickEvent.ServerTickEvent.Post e){if(!mode().startsWith("finish")||stage==99)return;var l=e.server().overworld();ticks++;if(stage==0&&ticks==1&&!mode().equals("finish-client"))for(var at:List.of(A,B,AdvancedInfusionChecks.S,M,F,M16FinishChecks.P))force(l,at);
  if(stage==10){if(ticks<250)return;check(matrix.job()==null&&((InfusionPedestal)l.getBlockEntity(M.below(2))).item().is(thaumcraft.crystals.CrystalContent.BLOCKS.get("aer").get().asItem())&&essence(l,M)==0,"Restart did not finish exactly once");M16FinishChecks.finishRead(l);Thaumcraft.LOGGER.info("INFUSION55_RESTART_OK: native ticking resumed absorption and produced one result without repaying essence");stage=99;e.server().halt(false);return;}
  if(stage==0){if(ticks<100||mode().equals("finish-client")&&actor==null)return;if(actor==null)actor=fake(l);grant(actor);force(l,M);thaumcraft.config.ThaumcraftConfig.allowChampionMobs.set(false);if(mode().equals("finish-client")){clientScene(l);stage=1;return;}for(var k:List.of(A,B,AdvancedInfusionChecks.S))force(l,k);AdvancedInfusionChecks.run(l,actor);styles(l);symmetry(l);dynamic(l);recovery(l);accidents(l);M16FinishChecks.run(l,actor);stage=20;ticks=0;return;}
  if(stage==20){if(ticks<80)return;M16FinishChecks.afterTicks(l);M16FinishChecks.save(l);prepareSave(l);stage=99;e.server().halt(false);return;}
  if(stage==3&&Files.exists(Path.of("../work/infusion55-show-m16"))){M16FinishChecks.clientScene(l,actor);stage=4;return;}
  if(stage==4){M16FinishChecks.clientTick(l);if(Files.exists(Path.of("../work/infusion55-finish-m16"))){e.server().tickRateManager().setFrozen(false);stage=5;}return;}
  if(stage==1){if(matrix.job()==null)return;expected=matrix.job().total();initial=essence(l,M);started=true;stage=2;Thaumcraft.LOGGER.info("INFUSION55_CLIENT_STARTED: native interaction, {} essence fixed in snapshot, cycle delay {}",expected,matrix.cycleDelay());}
  if(stage==2&&matrix.job()==null){var out=((InfusionPedestal)l.getBlockEntity(M.below(2))).item();check(InfusionEnchantments.level(out,InfusionEnchantments.Kind.SOUNDING)==4&&InfusionEnchantments.level(out,InfusionEnchantments.Kind.COLLECTOR)==1&&out.getHoverName().getString().equals("Advanced infusion proof")&&500-essence(l,M)==expected,"Client ritual result/cost mismatch");finished=true;stage=3;Thaumcraft.LOGGER.info("INFUSION55_CLIENT_COMPLETE: rank four plus Collector, full named tool preserved, exact {} essence, no duplicate result",expected);}
 }
